const items = $input.all();

if (items.length !== 1) {
  throw new Error('Expected exactly one webhook request.');
}

const input = items[0].json;

// In Webhook nodes, the JSON payload is usually contained in the body.
// The fallback also supports manual testing of the Code node.
const body = input.body ?? input;

const rawTitle = typeof body.title === 'string'
  ? body.title.trim()
  : '';

const content = typeof body.content === 'string'
  ? body.content.trim()
  : '';

// Empty notes are not allowed.
if (!content) {
  throw new Error('The content field is required and cannot be empty.');
}

// Optional safety limit: approximately 1 MB of text.
if (content.length > 1_000_000) {
  throw new Error('The note content is too large.');
}

// Use a safe default when no title is provided.
let safeTitle = rawTitle || 'Untitled Note';

// Remove characters that are problematic in Windows filenames
// or could be used for path traversal.
safeTitle = safeTitle
  .replace(/[<>:"/\\|?*\u0000-\u001F]/g, ' ')
  .replace(/\.\./g, ' ')
  .replace(/\s+/g, ' ')
  .replace(/[.\s]+$/g, '')
  .trim();

// Limit the filename length.
safeTitle = safeTitle.slice(0, 120).trim();

if (!safeTitle) {
  safeTitle = 'Untitled Note';
}

// Avoid reserved Windows filenames.
const reservedWindowsNames =
  /^(con|prn|aux|nul|com[1-9]|lpt[1-9])$/i;

if (reservedWindowsNames.test(safeTitle)) {
  safeTitle = `Note ${safeTitle}`;
}

// The destination folder is fixed and never derived from user input.
const allowedFolder = '00 Inbox/AI Imports';
const filename = `${safeTitle}.md`;
const vaultPath = `${allowedFolder}/${filename}`;

return [
  {
    json: {
      title: safeTitle,
      content,
      filename,
      vaultPath,
      allowedFolder,
    },
  },
];

